def soup_serving_probability(n):
    if n>4800:return 1.0
    from functools import lru_cache
    units=(n+24)//25
    @lru_cache(None)
    def solve(a,b):
        if a<=0 and b<=0:return .5
        if a<=0:return 1.0
        if b<=0:return 0.0
        return sum(solve(a-da,b-db) for da,db in ((4,0),(3,1),(2,2),(1,3)))/4
    return solve(units,units)

